#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

# Production setup for ticket #12: Supabase (free plan) + Vercel, so the app runs over HTTPS
# and installs on the iPhone. Run it from anywhere: it moves to the repo root first.
cd "$(dirname "$0")/.."

# Public values only. Not .env.production.local: Next.js loads that file in local production
# builds, and the tests must never reach the live database.
ENV_FILE=".env.wizard"

TOTAL_STAGES=10

banner "Tech Lead Trainer: production setup"

# ── 1 ──────────────────────────────────────────────────────────────────────
stage "Before you start"
say "This wizard creates the live database, connects Vercel, and puts the app on your iPhone."
say "It takes about 25 minutes. Nothing secret is written to a file."
step "You need a Supabase account and a Vercel account."
step "Vercel must be connected to the GitHub account lam-valamorgulis."
warn "Sign in to the app later with the SAME email as your Supabase account."
note "Supabase's built-in email only sends to your project team's addresses, 2 emails per hour."
note "Source: https://supabase.com/docs/guides/auth/auth-smtp"
pause

# ── 2 ──────────────────────────────────────────────────────────────────────
stage "Supabase: create the project"
open_url "https://supabase.com/dashboard/projects"
step "Click 'New project'. Name: tech-lead-trainer. Plan: Free."
step "Region: Southeast Asia (Singapore), the closest to Vietnam."
step "Click 'Generate a password'. Save it in your password manager now."
step "Create the project and wait until it is ready (about 2 minutes)."
say "The project ref is in the address bar: supabase.com/dashboard/project/<ref>"
ask SUPABASE_PROJECT_REF "Paste the project ref (20 letters):"
until [[ "$SUPABASE_PROJECT_REF" =~ ^[a-z]{20}$ ]]; do
  warn "A project ref is 20 lower-case letters, for example abcdefghijklmnopqrst."
  ask SUPABASE_PROJECT_REF "Paste the project ref:"
done
write_env SUPABASE_PROJECT_REF "$SUPABASE_PROJECT_REF"
ask_secret SUPABASE_DB_PASSWORD "Paste the database password (hidden, not saved):"

# ── 3 ──────────────────────────────────────────────────────────────────────
stage "Supabase CLI: sign in"
say "The command line needs your Supabase login to change the live database."
say "A browser window opens. Approve the login there."
pause "Press Enter to run: npx supabase login"
npx supabase login

# ── 4 ──────────────────────────────────────────────────────────────────────
stage "Supabase: create the tables"
say "This links the project, shows the migrations, then applies them to the LIVE database."
npx supabase link --project-ref "$SUPABASE_PROJECT_REF" --password "$SUPABASE_DB_PASSWORD"
npx supabase db push --linked --password "$SUPABASE_DB_PASSWORD" --dry-run
if confirm "Apply these migrations to the live database?"; then
  npx supabase db push --linked --password "$SUPABASE_DB_PASSWORD" --yes
else
  SKIPPED+=("Apply the migrations: npx supabase link, then npx supabase db push --linked")
  warn "Skipped. The app cannot work until the migrations are applied."
fi
# Unlink again, so every other command on this Mac keeps using local Supabase only.
npx supabase unlink >/dev/null 2>&1 || true
note "Unlinked: local commands use the Supabase on this Mac again."
pause

# ── 5 ──────────────────────────────────────────────────────────────────────
stage "Supabase: sign in with a 6-digit code"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/auth/providers"
step "Turn OFF the setting that lets new users sign up (named 'Allow new users to sign up')."
note "The app's server creates accounts only for emails on the allow list."
step "Open the Email provider. It stays ON."
step "Email OTP Length: 6. Email OTP Expiration: 3600 seconds. Save."
pause "Press Enter when the provider settings are saved"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/auth/templates/magic-link-or-otp"
pbcopy < supabase/templates/sign-in-code.html
say "The email body is now on your clipboard (supabase/templates/sign-in-code.html)."
step "Subject: Your Tech Lead Trainer code"
step "Body: select all and paste. It must show {{ .Token }} and no link. Save."
pause "Press Enter when the Magic Link template is saved"

# ── 6 ──────────────────────────────────────────────────────────────────────
stage "Supabase: API keys"
SUPABASE_URL="https://$SUPABASE_PROJECT_REF.supabase.co"
write_env NEXT_PUBLIC_SUPABASE_URL "$SUPABASE_URL"
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/settings/api-keys"
step "Copy the publishable key (it starts with sb_publishable_)."
ask SUPABASE_PUBLISHABLE_KEY "Paste the publishable key:"
until [[ "$SUPABASE_PUBLISHABLE_KEY" == sb_publishable_* ]]; do
  ask SUPABASE_PUBLISHABLE_KEY "It must start with sb_publishable_. Paste it again:"
done
write_env NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY "$SUPABASE_PUBLISHABLE_KEY"
step "Reveal and copy a secret key (it starts with sb_secret_)."
ask_secret SUPABASE_SECRET_KEY "Paste the secret key (hidden, not saved):"
until [[ "$SUPABASE_SECRET_KEY" == sb_secret_* ]]; do
  ask_secret SUPABASE_SECRET_KEY "It must start with sb_secret_. Paste it again:"
done

# ── 7 ──────────────────────────────────────────────────────────────────────
stage "Supabase: your email on the allow list"
say "Only emails on the allow list get a sign-in code."
ask OWNER_EMAIL "Your email (the one of your Supabase account):"
OWNER_EMAIL=$(printf '%s' "$OWNER_EMAIL" | tr '[:upper:]' '[:lower:]' | xargs)
until [[ "$OWNER_EMAIL" =~ ^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]+$ ]]; do
  ask OWNER_EMAIL "That does not look like an email. Type it again:"
  OWNER_EMAIL=$(printf '%s' "$OWNER_EMAIL" | tr '[:upper:]' '[:lower:]' | xargs)
done
write_env OWNER_EMAIL "$OWNER_EMAIL"
# Through the Supabase CLI login (Management API), not the REST API: the REST call with a
# secret key failed without a message on the first real run.
npx supabase db query --linked --project-ref "$SUPABASE_PROJECT_REF" \
  "insert into public.allowed_emails (email) values ('$OWNER_EMAIL') on conflict do nothing" >/dev/null || true
if npx supabase db query --linked --project-ref "$SUPABASE_PROJECT_REF" \
  "select email from public.allowed_emails where email = '$OWNER_EMAIL'" 2>/dev/null | grep -q "\"$OWNER_EMAIL\""; then
  printf '  %s✓%s %s is on the allow list\n' "$GREEN" "$RESET" "$OWNER_EMAIL"
else
  SKIPPED+=("Add your email to allowed_emails in the Supabase SQL editor")
  warn "Could not confirm the allow list. Add the email in the Supabase SQL editor."
fi
npx supabase unlink >/dev/null 2>&1 || true
pause

# ── 8 ──────────────────────────────────────────────────────────────────────
stage "Vercel: the project and its 3 settings"
open_url "https://vercel.com/new"
step "Import the GitHub repo lam-valamorgulis/tech-lead-trainer. Framework: Next.js."
step "Open 'Environment Variables'. Add these 3, for Production and Preview."
note "Do NOT add NEXT_PUBLIC_CONTENT_SET. It is for tests only."
for name in NEXT_PUBLIC_SUPABASE_URL NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY SUPABASE_SECRET_KEY; do
  case "$name" in
    NEXT_PUBLIC_SUPABASE_URL) value="$SUPABASE_URL" ;;
    NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY) value="$SUPABASE_PUBLISHABLE_KEY" ;;
    SUPABASE_SECRET_KEY) value="$SUPABASE_SECRET_KEY" ;;
  esac
  printf '%s' "$value" | pbcopy
  step "Name: $name   Value: on your clipboard now. Paste it."
  pause "Press Enter for the next one"
done
pbcopy < /dev/null
note "Clipboard cleared."
step "Click Deploy. The first deploy is from main and may fail: main has no app until 'ship'."
pause "Press Enter when the project exists"
open_url "https://vercel.com/dashboard"
step "Open the project → Settings → Deployment Protection."
step "Turn Vercel Authentication OFF and save, so your iPhone can open the preview."
note "Docs: https://vercel.com/docs/deployment-protection (Standard Protection guards previews)."
pause "Press Enter when it is off"

# ── 9 ──────────────────────────────────────────────────────────────────────
stage "Vercel: deploy sprint-1 and set the site address"
say "Vercel builds a preview for each push. sprint-1 was pushed before the project existed."
if confirm "Push one empty commit to sprint-1 to start its first preview?"; then
  # Built on the remote branch with commit-tree: your branch and files are not touched.
  git fetch -q origin sprint-1
  empty=$(git commit-tree "origin/sprint-1^{tree}" -p origin/sprint-1 \
    -m "chore: start the first Vercel preview of sprint-1")
  git push -q origin "$empty:refs/heads/sprint-1"
  printf '  %s✓%s pushed\n' "$GREEN" "$RESET"
else
  SKIPPED+=("Start a preview of sprint-1 (any push to sprint-1 does it)")
fi
open_url "https://vercel.com/dashboard"
step "Open the project → Deployments. Wait until the sprint-1 deployment is Ready."
step "Copy its branch address: it contains -git-sprint-1-. It stays the same for every new push."
ask APP_URL "Paste the sprint-1 address (https://...):"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"
if curl -fsS -o /dev/null "$APP_URL/manifest.webmanifest"; then
  printf '  %s✓%s the app answers at %s\n' "$GREEN" "$RESET" "$APP_URL"
else
  warn "The app did not answer. Check Deployment Protection and the build log."
fi
open_url "https://supabase.com/dashboard/project/$SUPABASE_PROJECT_REF/auth/url-configuration"
step "Site URL: $APP_URL   Save."
pause "Press Enter when the Site URL is saved"

# ── 10 ─────────────────────────────────────────────────────────────────────
stage "iPhone: install and sign in"
say "On the iPhone, open Safari (not another browser) at:"
printf '\n    %s%s%s\n\n' "$BOLD" "$APP_URL" "$RESET"
step "Tap Share → Add to Home Screen. The name is Tech Lead Trainer."
step "Open the app from the Home Screen. There is no Safari address bar."
step "Type $OWNER_EMAIL, tap Send code, and type the 6-digit code from the email."
note "No email? Check spam. The built-in email sends at most 2 per hour."
pause "Press Enter when you are signed in on the iPhone"

finish
say "Next: tell Claude 'iPhone works' (or what failed), so ticket #12 can be closed."
printf '\n'
